import{_ as o,c as d,o as c,aj as t}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Type Alias: FunctionTrigger","description":"","frontmatter":{},"headers":[],"relativePath":"reference/primitive-functions/api/type-aliases/FunctionTrigger.md","filePath":"reference/primitive-functions/api/type-aliases/FunctionTrigger.md"}'),r={name:"reference/primitive-functions/api/type-aliases/FunctionTrigger.md"};function n(a,e,i,s,l,h){return c(),d("div",null,[...e[0]||(e[0]=[t('<p><a href="./../README.html"><strong>primitive-functions</strong></a></p><hr><p><a href="./../globals.html">primitive-functions</a> / FunctionTrigger</p><h1 id="type-alias-functiontrigger" tabindex="-1">Type Alias: FunctionTrigger <a class="header-anchor" href="#type-alias-functiontrigger" aria-label="Permalink to “Type Alias: FunctionTrigger”">​</a></h1><blockquote><p><strong>FunctionTrigger</strong> = { <code>kind</code>: <code>&quot;http&quot;</code>; <code>runKey</code>: <code>string</code> | <code>null</code>; } | { <code>externalEventId</code>: <code>string</code> | <code>null</code>; <code>kind</code>: <code>&quot;webhook&quot;</code>; <code>webhookId</code>: <code>string</code>; <code>webhookKey</code>: <code>string</code>; } | { <code>kind</code>: <code>&quot;cron&quot;</code>; <code>manual?</code>: <code>true</code>; <code>name</code>: <code>string</code>; <code>scheduledFor</code>: <code>string</code>; <code>triggerId</code>: <code>string</code>; } | { <code>functionKey</code>: <code>string</code>; <code>kind</code>: <code>&quot;function&quot;</code>; <code>runId</code>: <code>string</code> | <code>null</code>; <code>runKey</code>: <code>string</code> | <code>null</code>; } | { <code>kind</code>: <code>&quot;manual&quot;</code>; <code>runKey</code>: <code>string</code> | <code>null</code>; <code>userId</code>: <code>string</code>; } | { <code>callId</code>: <code>string</code>; <code>kind</code>: <code>&quot;tool&quot;</code>; <code>sessionId</code>: <code>string</code>; <code>toolName</code>: <code>string</code>; <code>turnId</code>: <code>string</code>; } | { <code>kind</code>: <code>&quot;context&quot;</code>; <code>sessionId</code>: <code>string</code>; <code>turnId</code>: <code>string</code>; } | { <code>kind</code>: <code>&quot;history&quot;</code>; <code>sessionId</code>: <code>string</code>; <code>turnId</code>: <code>string</code>; } | { <code>db3Id</code>: <code>string</code>; <code>from</code>: <code>number</code>; <code>kind</code>: <code>&quot;db3&quot;</code>; <code>to</code>: <code>number</code>; <code>triggerId</code>: <code>string</code>; <code>type</code>: <code>string</code>; } | { <code>attempt</code>: <code>number</code>; <code>batch</code>: <code>number</code>; <code>kind</code>: <code>&quot;users-batch&quot;</code>; <code>startedByFunctionKey</code>: <code>string</code> | <code>null</code>; <code>walkRunId</code>: <code>string</code>; }</p></blockquote><p>What started this invocation. Narrow on <code>kind</code>.</p><p>The same union the runtime builds (<code>src/server-functions/trigger-descriptor.ts</code>), held identical by <code>tests/api/spec/function-trigger-declarations-3281.test.ts</code>: a field the fire path sets is declared here, and nothing is declared here that the fire path does not set.</p><h2 id="union-members" tabindex="-1">Union Members <a class="header-anchor" href="#union-members" aria-label="Permalink to “Union Members”">​</a></h2><h3 id="type-literal" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>kind</code>: <code>&quot;http&quot;</code>; <code>runKey</code>: <code>string</code> | <code>null</code>; }</p><p>An HTTP invocation: the caller is <code>ctx.user</code>.</p><p><code>runKey</code> is the key a <code>start</code> was coalesced by — what you passed as <code>runKey</code> to make the run a singleton — and null when the start named none, or when the call was an <code>invoke</code>, which coalesces nothing.</p><hr><h3 id="type-literal-1" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-1" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>externalEventId</code>: <code>string</code> | <code>null</code>; <code>kind</code>: <code>&quot;webhook&quot;</code>; <code>webhookId</code>: <code>string</code>; <code>webhookKey</code>: <code>string</code>; }</p><p>A verified webhook delivery to the function&#39;s own key.</p><h4 id="externaleventid" tabindex="-1">externalEventId <a class="header-anchor" href="#externaleventid" aria-label="Permalink to “externalEventId”">​</a></h4><blockquote><p><strong>externalEventId</strong>: <code>string</code> | <code>null</code></p></blockquote><p>The provider&#39;s event id (<code>X-Webhook-Event-Id</code>), when it sent one.</p><h4 id="kind" tabindex="-1">kind <a class="header-anchor" href="#kind" aria-label="Permalink to “kind”">​</a></h4><blockquote><p><strong>kind</strong>: <code>&quot;webhook&quot;</code></p></blockquote><h4 id="webhookid" tabindex="-1">webhookId <a class="header-anchor" href="#webhookid" aria-label="Permalink to “webhookId”">​</a></h4><blockquote><p><strong>webhookId</strong>: <code>string</code></p></blockquote><p>The platform&#39;s webhook row the delivery log lives under.</p><h4 id="webhookkey" tabindex="-1">webhookKey <a class="header-anchor" href="#webhookkey" aria-label="Permalink to “webhookKey”">​</a></h4><blockquote><p><strong>webhookKey</strong>: <code>string</code></p></blockquote><p>The webhook key, which is the function key.</p><hr><h3 id="type-literal-2" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-2" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>kind</code>: <code>&quot;cron&quot;</code>; <code>manual?</code>: <code>true</code>; <code>name</code>: <code>string</code>; <code>scheduledFor</code>: <code>string</code>; <code>triggerId</code>: <code>string</code>; }</p><p>A cron entry firing, scheduled or from the <code>functions triggers fire</code> diagnostic.</p><h4 id="kind-1" tabindex="-1">kind <a class="header-anchor" href="#kind-1" aria-label="Permalink to “kind”">​</a></h4><blockquote><p><strong>kind</strong>: <code>&quot;cron&quot;</code></p></blockquote><h4 id="manual" tabindex="-1">manual? <a class="header-anchor" href="#manual" aria-label="Permalink to “manual?”">​</a></h4><blockquote><p><code>optional</code> <strong>manual?</strong>: <code>true</code></p></blockquote><p>Present, and true, only on the diagnostic fire: nothing was scheduled.</p><h4 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h4><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>The <code>[[function.triggers.cron]]</code> entry&#39;s <code>name</code>.</p><h4 id="scheduledfor" tabindex="-1">scheduledFor <a class="header-anchor" href="#scheduledfor" aria-label="Permalink to “scheduledFor”">​</a></h4><blockquote><p><strong>scheduledFor</strong>: <code>string</code></p></blockquote><p>ISO 8601. The instant the fire was scheduled for; a diagnostic fire&#39;s is &quot;now&quot;.</p><h4 id="triggerid" tabindex="-1">triggerId <a class="header-anchor" href="#triggerid" aria-label="Permalink to “triggerId”">​</a></h4><blockquote><p><strong>triggerId</strong>: <code>string</code></p></blockquote><p>The platform&#39;s cron row.</p><hr><h3 id="type-literal-3" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-3" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>functionKey</code>: <code>string</code>; <code>kind</code>: <code>&quot;function&quot;</code>; <code>runId</code>: <code>string</code> | <code>null</code>; <code>runKey</code>: <code>string</code> | <code>null</code>; }</p><p>Another function started this one with <code>ctx.functions.start</code>.</p><p><code>functionKey</code> names the PARENT, and <code>runId</code> its run — null when the parent was a request invocation over HTTP, which writes no run row. <code>runKey</code> is the key the parent&#39;s start named, or null.</p><hr><h3 id="type-literal-4" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-4" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>kind</code>: <code>&quot;manual&quot;</code>; <code>runKey</code>: <code>string</code> | <code>null</code>; <code>userId</code>: <code>string</code>; }</p><p>An admin ran this function as the SYSTEM, from outside any trigger — <code>primitive functions invoke --as system</code>.</p><p><code>ctx.user</code> is null and the code runs with the app&#39;s system authority, as it does for a cron or webhook fire. <code>userId</code> names the admin who asked: attribution, never the principal the code runs as. <code>runKey</code> is the key the admin&#39;s start named, or null.</p><hr><h3 id="type-literal-5" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-5" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>callId</code>: <code>string</code>; <code>kind</code>: <code>&quot;tool&quot;</code>; <code>sessionId</code>: <code>string</code>; <code>toolName</code>: <code>string</code>; <code>turnId</code>: <code>string</code>; }</p><p>An agent turn called this function as one of its tools.</p><p><code>ctx.user</code> is the turn&#39;s initiator, whose <code>access</code> gate the call passed, and <code>ctx.tool</code> carries the session&#39;s ids, members and variables, and the turn&#39;s context, timezone and locale. <code>callId</code> is the same on every attempt of the call, so use it as an idempotency key. <code>toolName</code> is the declared tool name, which may differ from the function&#39;s key.</p><hr><h3 id="type-literal-6" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-6" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>kind</code>: <code>&quot;context&quot;</code>; <code>sessionId</code>: <code>string</code>; <code>turnId</code>: <code>string</code>; }</p><p>An agent turn asked this function for its turn context.</p><hr><h3 id="type-literal-7" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-7" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>kind</code>: <code>&quot;history&quot;</code>; <code>sessionId</code>: <code>string</code>; <code>turnId</code>: <code>string</code>; }</p><p>An agent turn asked this function for the history to send the model.</p><hr><h3 id="type-literal-8" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-8" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>db3Id</code>: <code>string</code>; <code>from</code>: <code>number</code>; <code>kind</code>: <code>&quot;db3&quot;</code>; <code>to</code>: <code>number</code>; <code>triggerId</code>: <code>string</code>; <code>type</code>: <code>string</code>; }</p><p>One flush of a db3 of a type a <code>[[function.triggers.db3]]</code> entry watches: a client&#39;s socket batch, a records-route write or a partial bulk that accepted at least one entry. <code>from</code> and <code>to</code> are the flush&#39;s first and last log numbers. The run&#39;s input carries the changed records&#39; keys and change kinds, not their values: read what you need through <code>ctx.db3(trigger.db3Id, trigger.type)</code>.</p><p>A watcher that writes the db3 it watches starts another run per flush, bounded only by its <code>ratePerMinute</code>; branch on <code>ctx.trigger.kind === &quot;db3&quot;</code> to skip the writes a flush of your own started.</p><hr><h3 id="type-literal-9" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-9" aria-label="Permalink to “Type Literal”">​</a></h3><p>{ <code>attempt</code>: <code>number</code>; <code>batch</code>: <code>number</code>; <code>kind</code>: <code>&quot;users-batch&quot;</code>; <code>startedByFunctionKey</code>: <code>string</code> | <code>null</code>; <code>walkRunId</code>: <code>string</code>; }</p><p>One batch of a users walk: at most 100 user ids the walk&#39;s query matched, in the run&#39;s input as <code>userIds</code>, beside the walk&#39;s own <code>input</code>. <code>walkRunId</code> is the walk&#39;s run and <code>batch</code> its number, the same on every attempt; <code>attempt</code> counts from 1, so a retried batch carries its first number and the same ids. <code>startedByFunctionKey</code> names the function that started the walk, and is null when an admin started it. A batch may run more than once, so make the function idempotent.</p>',77)])])}const g=o(r,[["render",n]]);export{p as __pageData,g as default};
